# Fix: Keep ALL boundary 6s, fill interior with 2

data = [
    [0, 0, 6, 0, 0, 0, 0, 0, 6],
    [0, 6, 0, 6, 0, 0, 0, 6, 0],
    [6, 0, 0, 0, 6, 0, 6, 0, 0],
    [0, 0, 0, 0, 0, 6, 0, 0, 0]
]

result = [[0]*9 for _ in range(4)]
for r in range(4):
    cols_6 = [c for c in range(9) if data[r][c] == 6]
    if cols_6:
        min_c = min(cols_6)
        max_c = max(cols_6)
        for c in range(min_c, max_c + 1):
            if data[r][c] == 6:
                result[r][c] = 6  # Keep boundary 6
            else:
                result[r][c] = 2  # Fill interior with 2

print("Result with interior=2 (better):")
for row in result:
    print(row)

